            if g[r][c]==bg and not vis[r][c]:
                comp=[(r,c)]; vis[r][c]=True; qq=deque([(r,c)])
                while qq:
                    a,b=qq.popleft()
                    for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+dr,b+dc
                        if 0<=na<h and 0<=nb<w and not vis[na][nb] and g[na][nb]==bg:
                            vis[na][nb]=True; comp.append((na,nb)); qq.append((na,nb))
                col=None
                for a,b in comp:
                    for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+dr,b+dc
                        if 0<=na<h and 0<=nb<w and g[na][nb]!=bg:
                            col=g[na][nb]
                fill=col^1 if col is not None else bg
                for a,b in comp: out[a][b]=fill
    return out
