    from collections import deque
    vis=[[False]*w for _ in range(h)]; dq=deque()
    for r in range(h):
        for c in range(w):
            if (r in(0,h-1) or c in(0,w-1)) and g[r][c]==bg and not vis[r][c]:
                vis[r][c]=True; dq.append((r,c))
    while dq:
        r,c=dq.popleft()
        for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<h and 0<=nc<w and not vis[nr][nc] and g[nr][nc]==bg:
                vis[nr][nc]=True; dq.append((nr,nc))
    for r in range(h):
        for c in range(w):
            if g[r][c]==bg and not vis[r][c]:
                comp=[(r,c)]; vis[r][c]=True; qq=deque([(r,c)])
                while qq:
                    a,b=qq.popleft()
                    for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+dr,b+dc
                        if 0<=na<h and 0<=nb<w and not vis[na][nb] and g[na][nb]==bg:
                            vis[na][nb]=True; comp.append((na,nb)); qq.append((na,nb))
                fill=7 if len(comp)%2==1 else 2
                for a,b in comp: g[a][b]=fill
    return g
